from pathlib import Path
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else '.')

def repl(path, old, new):
    p = root / path
    s = p.read_text()
    if old not in s:
        raise SystemExit(f'missing pattern in {path}: {old[:100]!r}')
    p.write_text(s.replace(old, new, 1))

# 1. Application: consume an already-visible Pi directly.
repl('src/infer.rs', '''        while let Some(arg) = args.pop() {\n            let fty_f = self.force_all(depth, fty);\n            let (domain, body) = match fty_f {\n                Value::Pi { domain, body, .. } => (*domain, body),\n                _ => panic!("expected a pi type"),\n            };''', '''        while let Some(arg) = args.pop() {\n            let (domain, body) = match fty {\n                Value::Pi { domain, body, .. } => (*domain, body),\n                _ => match self.force_all(depth, fty) {\n                    Value::Pi { domain, body, .. } => (*domain, body),\n                    _ => panic!("expected a pi type"),\n                },\n            };''')

# 2. Sort: consume an already-visible Sort directly.
repl('src/infer.rs', '''    pub(crate) fn ensure_sort_v(&mut self, depth: u32, v: V<'t>) -> LevelPtr<'t> {\n        match self.force_all(depth, v) {\n            Value::Sort { level , .. } => *level,\n            _ => panic!("expected a sort"),\n        }\n    }''', '''    pub(crate) fn ensure_sort_v(&mut self, depth: u32, v: V<'t>) -> LevelPtr<'t> {\n        match v {\n            Value::Sort { level, .. } => *level,\n            _ => match self.force_all(depth, v) {\n                Value::Sort { level, .. } => *level,\n                _ => panic!("expected a sort"),\n            },\n        }\n    }''')

# 3. Projection parameter telescope: direct Pi when already visible.
repl('src/infer.rs', '''        for p in params.iter().take(num_params).copied() {\n            match self.force_all(depth, cur) {\n                Value::Pi { domain, body, .. } => cur = self.apply_closure(depth, body, p, Some(*domain)),\n                _ => panic!("ran out of param telescope in projection"),\n            }\n        }''', '''        for p in params.iter().take(num_params).copied() {\n            match cur {\n                Value::Pi { domain, body, .. } => cur = self.apply_closure(depth, body, p, Some(*domain)),\n                _ => match self.force_all(depth, cur) {\n                    Value::Pi { domain, body, .. } => cur = self.apply_closure(depth, body, p, Some(*domain)),\n                    _ => panic!("ran out of param telescope in projection"),\n                },\n            }\n        }''')

# 4. Projection final field: direct Pi when already visible.
repl('src/infer.rs', '''        match self.force_all(depth, cur) {\n            Value::Pi { domain, .. } => {\n                if struct_ty_is_prop && !self.is_prop_type(depth, domain) {\n                    panic!("projection of a non-proof field from a Prop structure")\n                }\n                *domain\n            }\n            _ => panic!("ran out of constructor telescope getting projection field"),\n        }''', '''        match cur {\n            Value::Pi { domain, .. } => {\n                if struct_ty_is_prop && !self.is_prop_type(depth, domain) {\n                    panic!("projection of a non-proof field from a Prop structure")\n                }\n                *domain\n            }\n            _ => match self.force_all(depth, cur) {\n                Value::Pi { domain, .. } => {\n                    if struct_ty_is_prop && !self.is_prop_type(depth, domain) {\n                        panic!("projection of a non-proof field from a Prop structure")\n                    }\n                    *domain\n                }\n                _ => panic!("ran out of constructor telescope getting projection field"),\n            },\n        }''')

# 5. Conversion: unify() has already forced the pair before unify_no_cache.
repl('src/conv.rs', '''        let (t, t2) = (self.force_thunk(depth, x), self.force_thunk(depth, y));\n        if let Some(r) = self.conv_nat::<RIGID>(depth, t, t2) {''', '''        let (t, t2) = (x, y);\n        if let Some(r) = self.conv_nat::<RIGID>(depth, t, t2) {''')

# 6. Spine probe: avoid materializing a temporary Vec of pairs that is consumed once.
p = root / 'src/conv.rs'
s = p.read_text()
start = s.index('    fn probe_pairs(')
end = s.index('    fn unfold_pair(', start)
streaming = '''    fn probe_shape_ok(&self, sx: S<'t>, sy: S<'t>) -> bool {\n        match (sx, sy) {\n            (Spine::Empty, Spine::Empty) => true,\n            (Spine::Snoc { prev: pa, elim: ea, .. }, Spine::Snoc { prev: pb, elim: eb, .. }) => {\n                if !self.probe_shape_ok(pa, pb) { return false; }\n                match (ea.view(), eb.view()) {\n                    (ElimView::App(_), ElimView::App(_)) => true,\n                    (ElimView::Proj { ty_name: tx, idx: ix }, ElimView::Proj { ty_name: ty, idx: iy }) => tx == ty && ix == iy,\n                    _ => false,\n                }\n            }\n            _ => false,\n        }\n    }\n\n    fn probe_stream(&mut self, depth: u32, sx: S<'t>, sy: S<'t>, sig: Sig, limit: u32, decided: &mut bool) -> bool {\n        match (sx, sy) {\n            (Spine::Empty, Spine::Empty) => true,\n            (Spine::Snoc { prev: pa, elim: ea, .. }, Spine::Snoc { prev: pb, elim: eb, .. }) => {\n                if !self.probe_stream(depth, pa, pb, sig, limit, decided) { return false; }\n                match (ea.view(), eb.view()) {\n                    (ElimView::App(va), ElimView::App(vb)) => {\n                        let idx = pa.len();\n                        if idx < limit && sig.arg_is_ignorable(idx) { return true; }\n                        self.tc_cache.probe_budget = Self::PROBE_CAP;\n                        self.tc_cache.probe_exhausted = false;\n                        self.tc_cache.probe_depth = 1;\n                        let ok = self.unify::<true>(depth, va, vb);\n                        self.tc_cache.probe_depth = 0;\n                        if self.tc_cache.probe_exhausted {\n                            self.tc_cache.conv_cache_neg_probe.clear();\n                            *decided = false;\n                            return true;\n                        }\n                        ok\n                    }\n                    (ElimView::Proj { .. }, ElimView::Proj { .. }) => true,\n                    _ => false,\n                }\n            }\n            _ => false,\n        }\n    }\n\n    fn spine_probe(&mut self, depth: u32, sx: S<'t>, sy: S<'t>, sig: Sig, limit: u32) -> bool {\n        if std::ptr::eq(sx, sy) { return true; }\n        if self.tc_cache.probe_depth > 0 { return self.unify_spine::<true>(depth, sx, sy, sig, limit); }\n        if !self.probe_shape_ok(sx, sy) { return false; }\n        let outer = std::mem::replace(&mut self.tc_cache.probe_exhausted, false);\n        let mut decided = true;\n        let ok = self.probe_stream(depth, sx, sy, sig, limit, &mut decided);\n        self.tc_cache.probe_exhausted = outer;\n        ok && decided\n    }\n\n'''
p.write_text(s[:start] + streaming + s[end:])
print('V4_RETAINED6_APPLIED=YES')
